{"packet_id":"D041-01","doc_id":"D041","jurisdiction":"Los Angeles, CA","category":"rent_increase_limits","lifecycle":"enacted","title":"Los Angeles Rent Stabilization Ordinance rent increase limits","requirement":"Landlords of RSO units may raise rent only once every 12 months by the allowable rent increase percentage; certain increases (capital improvement, renovation, seismic retrofit) require LAHD approval. Since February 2, 2026 the utility increase and the extra 10% for a dependent are barred.","key_value":null,"coverage_conditions":"Rental properties first built on or before October 1, 1978, including apartments, condominiums, townhomes, duplexes, ADUs, mobile homes and two or more single-family units on one parcel.","applicability":{"conditions":[{"type":"built","role":"covered","op":"on_or_before","date":"1978-10-01","basis":"construction"}],"per_tenancy":"Rent amounts are not regulated for condominium or townhome tenancies that commenced after December 31, 1995.","coverage_quotes":["Generally, the RSO applies to rental properties that were first built on or before October 1, 1978","Condominium (Rent amount is not regulated for tenancies that commenced after December 31, 1995)"]},"exemptions":"Luxury exemption where the landlord shows the monthly rent charged on or before May 31, 1978 met the threshold; condominium and townhome rent amounts for tenancies commencing after December 31, 1995.","penalty":null,"effective_date":null,"valid_through":null,"citation":"Los Angeles Rent Stabilization Ordinance (L.A.M.C. §151.00 et seq.)","quoted_span":"Rent may be increased once every 12 months by the allowable rent increase percentage","interaction":null,"relations":[],"confidence":0.75,"conflict_flag":false,"conflict_note":null}
{"packet_id":"D041-01","doc_id":"D041","jurisdiction":"Los Angeles, CA","category":"just_cause_eviction","lifecycle":"enacted","title":"Los Angeles Rent Stabilization Ordinance just cause eviction and relocation","requirement":"A landlord of an RSO unit may end a tenancy only for the listed at-fault or no-fault reasons, such as nonpayment, nuisance or owner move-in. No-fault evictions require relocation assistance and termination notices must be filed with LAHD within three business days of service.","key_value":"3 business days","coverage_conditions":"All rental units subject to the City's Rent Stabilization Ordinance.","applicability":{"conditions":[{"type":"built","role":"covered","op":"on_or_before","date":"1978-10-01","basis":"construction"}],"per_tenancy":"No-fault evictions (owner or resident manager move-in, demolition, government order, conversion to affordable housing) trigger tenant relocation assistance.","coverage_quotes":["Generally, the RSO applies to rental properties that were first built on or before October 1, 1978"]},"exemptions":null,"penalty":null,"effective_date":null,"valid_through":null,"citation":"Los Angeles Rent Stabilization Ordinance (L.A.M.C. §151.00 et seq.)","quoted_span":"must be filed with the Los Angeles Housing Department (LAHD) within three (3) business days of service on the tenant","interaction":null,"relations":[],"confidence":0.75,"conflict_flag":false,"conflict_note":null}
